!function(){"use strict";function e(){if("secure.dol.state.nj.us"===window.location.hostname){const e="G-2F7W0D0NDJ",t=document.createElement("script");t.src=`https://www.googletagmanager.com/gtag/js?id=${e}`,document.head.appendChild(t);const i=document.createElement("script");i.innerHTML=`window.dataLayer = window.dataLayer || []; function gtag(){dataLayer.push(arguments);} gtag('js', new Date()); gtag('config', '${e}');`,document.head.appendChild(i)}}const t="https://beta.nj.gov/files/tdi-fli-claim-status/assets";function i(e,...t){return String.raw({raw:e},...t)}function n(){return window.innerWidth>768}function o(){!function(){let e=document.querySelector("link[rel~='icon']");null==e&&(e=document.createElement("link"),e.rel="icon",document.head.appendChild(e)),e.href="https://beta.nj.gov/files/favicon.ico"}(),e(),function(){if(!n()){const e=document.createElement("meta");e.name="viewport",e.content="width=device-width, initial-scale=1",document.getElementsByTagName("head")[0]?.appendChild(e);const t=document.getElementsByTagName("img");for(let e=0;e<t.length;e++){const i=t[e];i.style.width="100%",i.style.height="auto"}}}(),function(){const e=document.querySelector("table#ContentPlaceHolder1_tblContent");if(!e)throw new Error("Cannot find HTML.");{const t=document.createElement("div");t.innerHTML='\n      <img\n        src="https://beta.nj.gov/files/dol_logo.png"\n        height="60"\n        alt="Official logo for the New Jersey Department of Labor"\n        style="margin-top: 36px; margin-bottom: 8px; margin-left: 8px; margin-right: 8px"\n      />\n      <h1>Application for State Temporary Disability Benefits</h1>\n      Welcome to the New Jersey Division of Temporary Disability Insurance online application.\n      <hr>\n      <h2>Instructions for Filing Online</h2>\n      <p>It is your responsibility to file this claim promptly. Your claim must be filed within thirty (30) days of the beginning of your disability period. Benefits may be denied or reduced if your claim is filed late.</p>\n      <p>To use this application, you will need a printer. It is your responsibility to provide your health care provider with the instructions to file online. <strong>Any missing information may cause your application to be denied.</strong></p>\n      <p>Questions noted by an asterisk (*) are required and must be answered. You will not be allowed to proceed until that question has a response.</p>\n      <p>Allow approximately thirty (30) minutes to complete this application. If you begin the application but are unable to finish, you will have fourteen (14) days to return and complete your claim or your data will be removed. You will then need to restart the application process.\n      If your disability date is in the future, you must also return to certify your claim within fourteen (14) days after your first date of disability or your data will be removed. \n      You will then need to restart the application process.</p>\n      <p>After submitting your application, you will be provided a confirmation. Keep this confirmation for your records, as it is proof that you filed your claim successfully.</p>\n      <p>If you require any assistance with your claim, call:\n      <ul>\n      <li>Customer Service Section (609) 292-7060</li>\n      <li>Telecommunication Device for the Deaf (609) 292-8319</li>\n      <li>New Jersey Relay Service: TT user 1-800-852-7899, Voice User 1-800-852-7897</li>\n      </ul></p>\n      <hr>\n      <h2>After Submitting Your Application</h2>\n      <p>If you recover or return to work earlier than expected, report this date immediately to the Division of Temporary Disability Insurance to avoid overpayment.</p>\n      <hr>\n      <h2>Data Privacy and Security</h2>\n      <p>The information collected as a result of your application is private data and cannot be released except when authorized by state or federal law, by court order or with your permission.</p>\n      <p>The information you or your health care provider submit may be used for any New Jersey Department of Labor and Workforce Development business. It may be shared with other state or federal agencies as permitted by law.</p>\n      <p>Precautions are taken to keep the information you provide in this application private and secure. The online application uses a secure connection and the data submitted is encrypted. \n      Using a shared computer to complete this application may enable others to view your personal information.</p>\n      <hr>\n      <p>I have read the above information and wish to file an Application For State Temporary Disability Benefits.</p>\n      <button\n        style="background-color: #0076D6; border: none; color: #fff; padding: 12px 20px; cursor: pointer; border-radius: 4px; font-weight: 700; font-size: 16px; line-height: 24px; outline-offset: 0.25rem; margin: 0 0 20px 20px;"\n        onclick="__doPostBack(\'ctl00$ContentPlaceHolder1$chkAgree\', \'\')"\n      >\n        Agree & Continue\n      </button>\n    ',e.replaceWith(t)}}()}i`<header style="padding:10px 20px;background-color:#000;color:#fff;font-size:13px;line-height:150%" id="header"><div style="margin-bottom:4px"><b>New Jersey Department of Labor and Workforce Development</b></div><a href="https://www.nj.gov/labor/myleavebenefits/" style="text-decoration:underline;color:#fff;text-underline-offset:2px">myLeaveBenefits.nj.gov</a></header>`,i`<footer id="helpSection" style="background-color:#eff6fb;padding:20px ${n()?"54px":"13px"};border-top:1px solid #0b4778;color:#000"><h3 style="margin:0;font-size:22px;line-height:32px;margin-bottom:8px">Need help?</h3><div style="display:grid;grid-template-columns:min-content auto;gap:16px;margin-bottom:8px"><div><img src="${t}/phone.svg" alt=""></div><div style="line-height:21px"><strong>Call</strong> <a href="tel:609-292-7060">609-292-7060</a> | (8:00am - 4:30pm, Monday - Friday) Wait times are shortest Wednesday - Friday</div><div><img src="${t}/fax.svg" alt=""></div><div style="line-height:21px"><strong>Fax</strong> 609-984-4138</div><div><img src="${t}/mail.svg" alt=""></div><div style="line-height:21px"><strong>Mail</strong><br>Division of Temporary Disability and Family Leave Insurance<br>PO Box 387 Trenton, New Jersey 08625-0387</div><div><img src="${t}/email.svg" alt=""></div><div style="line-height:21px"><a href="https://www.nj.gov/labor/myleavebenefits/help/contact/contact-form.shtml" target="_blank" style="text-underline-offset:2px"><strong>Email</strong></a></div><div><img src="${t}/info.svg" alt=""></div><div style="line-height:21px"><a href="https://www.nj.gov/labor/myleavebenefits/worker/resources/" target="_blank" style="text-underline-offset:2px"><strong>Helpful resources</strong></a></div></div><div>Due to technical constraints, you can access this claim status checker 8:00am - 4:30pm, Monday - Friday.</div></footer>`,i`<a href="#header" style="font-size:16px;color:#0b4778;text-underline-offset:2.5px">Return to top</a>`,"loading"===document.readyState?window.addEventListener("DOMContentLoaded",(()=>{o()})):o()}();
